@router.post('/admin/series', status_code=201, dependencies=[Depends(admin)])
def crear_serie(datos: NuevaSerie):
    ahora = reloj.ahora()
    objetivo = DIAS.index(datos.dia)
    inicios = []
    dia = datos.desde
    while dia <= datos.hasta:
        if dia.weekday() == objetivo and dia not in CIERRES:
            inicio = a_utc(dia, datos.hora)
            if inicio > ahora:
